import { useEffect, useRef, useState } from 'react';
import { Board } from '../board/Board.tsx';
import { GameStatus } from '../status/GameStatus.tsx';
import { isWon } from '../game.ts';
import { formatElapsed } from '../elapsed-time.ts';
import { useGame } from '../session/use-game.ts';
import { createTournament, currentMatch, currentPlayer, decodeTournament, nextMatch, recordResult } from './tournament.ts';
import type { Tournament } from './tournament.ts';
import type { BoardFocus } from '../board/Board.tsx';
import './tournament.css';

const HISTORY_KEY = 'neon-pairs.tournaments.v1';

function readHistory(): Tournament[] {
  try {
    const raw: unknown = JSON.parse(localStorage.getItem(HISTORY_KEY) ?? '[]');
    if (!Array.isArray(raw)) return [];
    return raw.flatMap((item: unknown) => {
      const tournament = decodeTournament(JSON.stringify(item));
      return tournament?.phase === 'complete' ? [tournament] : [];
    });
  } catch {
    return [];
  }
}

export function TournamentScreen({ back }: { back(): void }) {
  const controller = useGame();
  const { session } = controller;
  const board = useRef<BoardFocus>(null);
  const [count, setCount] = useState(4);
  const [names, setNames] = useState<string[]>(Array(8).fill(''));
  const [tournament, setTournament] = useState<Tournament | null>(null);
  const [history, setHistory] = useState(readHistory);
  const [json, setJson] = useState('');
  const [notice, setNotice] = useState('');

  useEffect(() => {
    if (tournament?.phase !== 'playing' || !isWon(session.game)) return;
    setTournament((current) => current?.phase === 'playing'
      ? recordResult(current, { moves: session.game.moves, elapsedMs: Math.floor(session.game.elapsedMs) })
      : current);
  }, [tournament, session.game]);

  function saveFinished(finished: Tournament): void {
    const updated = [finished, ...history];
    setHistory(updated);
    try { localStorage.setItem(HISTORY_KEY, JSON.stringify(updated)); } catch { setNotice('Tournament finished, but browser storage is unavailable. Export it to keep a copy.'); }
  }

  function exportTournament(): void {
    if (!tournament) {
      setJson(JSON.stringify({ version: 1, setup: true, count, names }, null, 2));
    } else {
      const snapshot = tournament.phase === 'playing' ? controller.exportSnapshot() : null;
      setJson(JSON.stringify({ ...tournament, snapshot }, null, 2));
    }
    setNotice('Tournament JSON exported.');
  }

  function loadTournament(): void {
    try {
      const setup: unknown = JSON.parse(json);
      if (typeof setup === 'object' && setup !== null && 'setup' in setup && setup.setup === true && 'version' in setup && setup.version === 1 && 'count' in setup && (setup.count === 4 || setup.count === 8) && 'names' in setup && Array.isArray(setup.names) && setup.names.length === 8 && setup.names.every((name: unknown) => typeof name === 'string' && name.length <= 80)) {
        setCount(setup.count);
        setNames(setup.names);
        setTournament(null);
        setNotice('Tournament setup loaded.');
        return;
      }
    } catch { /* Report invalid input below. */ }
    const loaded = decodeTournament(json);
    if (!loaded) { setNotice('Invalid tournament JSON.'); return; }
    if (loaded.phase === 'playing' && loaded.snapshot) controller.loadSnapshot(loaded.snapshot);
    setTournament(loaded);
    setNotice(loaded.phase === 'playing' ? 'Tournament loaded. Resume the turn to continue.' : 'Tournament loaded.');
  }

  function startTurn(): void {
    if (!tournament) return;
    controller.loadBoard(currentMatch(tournament).boardCode);
    setTournament({ ...tournament, phase: 'playing', snapshot: null });
    setNotice('');
  }

  function advanceMatch(): void {
    if (!tournament) return;
    const next = nextMatch(tournament);
    setTournament(next);
    if (next.phase === 'complete') saveFinished(next);
  }

  const match = tournament ? currentMatch(tournament) : null;
  const champion = tournament?.phase === 'complete' ? tournament.rounds.at(-1)?.[0]?.winner : null;
  return (
    <main>
      <header><p className="eyebrow">A little focus. A perfect pair.</p><h1>Tournament</h1></header>
      <p className="tournament-rule">Each player plays the same deal. Fewer moves wins; ties go to the faster time, then the first player.</p>
      {!tournament ? (
        <>
          <form className="tournament-setup" onSubmit={(event) => {
            event.preventDefault();
            const selected = names.slice(0, count).map((name) => name.trim());
            if (selected.some((name) => !name)) { setNotice('Enter a name for every player.'); return; }
            setTournament(createTournament(selected, session.game.size));
            setNotice('');
          }}>
            <label htmlFor="player-count">Players</label>
            <select id="player-count" className="control" value={count} onChange={(event) => setCount(Number(event.currentTarget.value))}>
              <option value={4}>4</option><option value={8}>8</option>
            </select>
            <div className="player-inputs">{names.slice(0, count).map((name, index) => (
              <div key={index}><label htmlFor={`player-${index + 1}`}>Player {index + 1}</label>
                <input id={`player-${index + 1}`} className="control" maxLength={80} required value={name} onChange={(event) => setNames(names.map((old, i) => i === index ? event.currentTarget.value : old))} />
              </div>
            ))}</div>
            <div className="control-row"><button className="control" type="submit">Start tournament</button><button className="control" type="button" onClick={back}>Back to game</button></div>
          </form>
          <section className="tournament-section"><h2>Past tournaments</h2>
            {history.length === 0 ? <p>No finished tournaments yet.</p> : <ul>{history.map((past, index) => {
              const winner = past.rounds.at(-1)?.[0]?.winner;
              return <li key={index}><button type="button" className="control" onClick={() => { setTournament(past); setNotice(''); }}>Champion: {winner === null || winner === undefined ? '' : past.names[winner]}</button></li>;
            })}</ul>}
          </section>
        </>
      ) : (
        <>
          {champion !== null && champion !== undefined ? <p className="champion">Champion: {tournament.names[champion]}</p> : match && <p className="now-playing">Now playing: {tournament.names[currentPlayer(match)]}</p>}
          {tournament.phase === 'ready' && <button type="button" className="control" onClick={startTurn}>Start turn</button>}
          {tournament.phase === 'playing' && <>
            {session.paused && <button type="button" className="control" onClick={() => { controller.resume(); board.current?.focusRemembered(); }}>Resume turn</button>}
            <GameStatus game={session.game} best={undefined} celebration={session.celebration} />
            <p id="board-help" className="help">Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space reveals a card.</p>
            <div className="game-result"><p role="status" aria-live="polite" aria-atomic="true"><span key={session.announcement}>{session.feedback}</span></p></div>
            <Board key={session.generation} game={session.game} activate={controller.activate} ref={board} />
