    const snapshot = await page.getByLabel('Snapshot JSON', { exact: true }).inputValue();
    const loadEvents = [
      {
        stage: 'invalid-board',
        field: 'Board code',
        value: 'invalid',
        button: 'Load board',
        notice: 'Invalid board code.',
      },
      {
        stage: 'invalid-snapshot',
        field: 'Snapshot JSON',
        value: '{',
        button: 'Load snapshot',
