  let tournament = createTournament(['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H'], 4);
  for (let match = 0; match < 7; match++) {
    tournament = recordResult(tournament, { moves: 8, elapsedMs: 1000 });
